class GenericAlarmVerification(GenericBts):
    """Alarm keywords for eNB and gNB"""

    def __init__(self, bts_type, log, ru):
        """
        Constructor of GenericAlarm class.
        """
        super(GenericAlarmVerification, self).__init__(bts_type=bts_type)
        self.log = log
        self.ru = ru
        self.alarms_watcher = {}
        self.alarms_log_dir = None
        self.alarm_log_path = None
        self.logs_collection_in_progress = False
        self._logs_collection_end_timestamp = None

    @login_logout
    def verify_alarms_are_not_active(self, alarms_to_be_verified=[], bts_id=0, du_id=0, timeout=30):
        """
        Verify is there alarms are not active on BTS
        :param alarms_to_be_verified: list of allowed alarms to be checked if not active, format, available values list
        values: {"faultName": "name", "faultId": ....} or fault_id
        :param bts_id: ID of BTS
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param timeout: timeout for admin API
        :return: None
        """
        all_active_alarms = self.admin.get_active_alarms(connection=self.rest_alias.format(bts_id, du_id),
                                                         timeout=timeout)
        active_alarms_converted = self._convert_to_alarms_objects(all_active_alarms)
        alarms_to_be_verified_converted = self._convert_to_alarms_objects(alarms_to_be_verified)
        active_alarms = []
        for alarm in active_alarms_converted:
            if alarm in alarms_to_be_verified_converted:
                active_alarms.append(alarm)
        if active_alarms:
            raise UnallowedAlarms("There are not allowed alarms active: {}".format(active_alarms))

    @login_logout
    def verify_alarm_is_active(self, fault_name, fault_id=None, alarm_id=None, severity=None, bts_id=0, du_id=0,
                               timeout=30, unit_path=None, reason=None):
        """
        Verify alarm is active
        :param fault_name: name of fault
        :param fault_id: Id of fault
        :param alarm_id: Id of alarm
        :param severity: severity of fault
        :param bts_id: ID of BTS
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param timeout: timeout for admin API
        :param unit_path: unit_path of fault
        :param reason: supplementary info of fault
        :return: None
        """
        all_active_alarms = self.admin.get_active_alarms(connection=self.rest_alias.format(bts_id, du_id),
                                                         timeout=timeout)
        active_alarms_converted = self._convert_to_alarms_objects(all_active_alarms)
        alarm_to_check = self._convert_to_alarms_objects([{'fault_name': fault_name,
                                                           'fault_id': fault_id,
                                                           'alarm_id': alarm_id,
                                                           'severity': severity,
                                                           'unit_path': unit_path,
                                                           'reason': reason}])[0]
        if alarm_to_check not in active_alarms_converted:
            raise AlarmIsNotActive("Alarm {} is not active".format(alarm_to_check))
        logging.info("Alarm {} is active".format(alarm_to_check))

    @login_logout
    def verify_allowed_alarms(self, allowed_alarms, bts_id=0, du_id=0, timeout=30):
        """
        Verify is there unexpected alarms
        :param allowed_alarms: list of allowed alarms
        :param bts_id: ID of BTS
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param timeout: timeout for admin API
        :return: None
        """
        active_alarms = self.admin.get_active_alarms(connection=self.rest_alias.format(bts_id, du_id), timeout=timeout)
        active_alarms_converted = self._convert_to_alarms_objects(active_alarms)
        allowed_alarms_converted = self._convert_to_alarms_objects(allowed_alarms)

        unallowed_alarms = [active_alarm for active_alarm in active_alarms_converted
                            if active_alarm not in allowed_alarms_converted]
        unallowed_alarms_without_warnings = self._remove_and_log_warnings(unallowed_alarms)

        if unallowed_alarms_without_warnings:
            raise UnallowedAlarms("There are not allowed alarms active: {}".format(unallowed_alarms_without_warnings))
        else:
            logging.info("No or only allowed alarms active")

    @staticmethod
    def _remove_and_log_warnings(active_alarms):
        alarms_without_warnings = []
        for alarm in active_alarms:
            if alarm.severity.lower() == 'warning':
                logging.warning("`{}` warning is active on BTS".format(alarm.fault_name))
                logging.debug(alarm)
            else:
                alarms_without_warnings.append(alarm)

        return alarms_without_warnings

    @login_logout
    def verify_alarm_is_not_active(self, fault_name, fault_id=None, alarm_id=None, severity=None, bts_id=0, du_id=0,
                                   timeout=30):
        """
        Verify alarm is not active
        :param fault_name: name of fault
        :param fault_id: Id of fault
        :param alarm_id: Id of alarm
        :param severity: severity of fault
        :param bts_id: ID of BTS
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param timeout: timeout for admin API
        :return: None
        """
        all_active_alarms = self.admin.get_active_alarms(connection=self.rest_alias.format(bts_id, du_id),
                                                         timeout=timeout)
        active_alarms_converted = self._convert_to_alarms_objects(all_active_alarms)

        alarm_to_check = self._convert_to_alarms_objects([{'fault_name': fault_name,
                                                           'fault_id': fault_id,
                                                           'alarm_id': alarm_id,
                                                           'severity': severity}])[0]

        if alarm_to_check in active_alarms_converted:
            raise AlarmIsActive("Alarm {} is active".format(alarm_to_check))
        logging.info("Alarm {} is not active".format(alarm_to_check))

    @login_logout
    def verify_mandatory_alarms(self, mandatory_alarms, bts_id=0, du_id=0, timeout=30):
        """
        Verify is there unexpected alarms
        :param mandatory_alarms: list of mandatory alarms
        :param bts_id: ID of BTS
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param timeout: timeout for admin API
        :return: None
        """
        active_alarms = self.admin.get_active_alarms(connection=self.rest_alias.format(bts_id, du_id), timeout=timeout)
        active_alarms_converted = self._convert_to_alarms_objects(active_alarms)
        mandatory_alarms_converted = self._convert_to_alarms_objects(mandatory_alarms)
        absent_mandatory_alarms = [alarm for alarm in mandatory_alarms_converted
                                   if alarm not in active_alarms_converted]

        if absent_mandatory_alarms:
            raise AbsentMandatoryAlarms("Some mandatory alarms are not active: {}".format(absent_mandatory_alarms))
        logging.info("All mandatory alarms are active")

    def start_watching_alarms(self, allowed_alarms=None, interface='mplane', interval=2.0, bts_id=0, du_id=0,
                              log_dir=None, timeout=120):
        """
        Start running alarms watcher.
        :param allowed_alarms: list of allowed faults' names
        :param interface: connect via 'mplane' or 'lmp'. Default mplane.
        :param interval: time interval between consecutive requests to BTS for active alarms;
        :param bts_id: ID of gNB. Default 0.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]. Default 0.
        :param log_dir: directory where logs are stored - if not defined then default logs path will be used
        :param timeout: timeout for connection to admin API
        :return: None
        """
        alias = self.rest_alias.format(bts_id, du_id)
        self.alarms_watcher[alias] = alarms_watchdog()
        allowed_alarms_list = self._convert_to_alarms_objects(allowed_alarms)
        if log_dir is None:
            log_dir = get_log_path()
        base_alarm_dir = os.path.join(log_dir, 'alarms_watchdog', alias)
        bts_conf = self.get_bts_config(bts_id=bts_id)
        if interface == 'lmp':
            bts_conf_http_conn_via_lmp = copy.deepcopy(bts_conf)
            bts_conf_http_conn_via_lmp.cu.oam_http_connection_details.addr = \
                self._get_lmp_ip_address(bts_id=bts_id, du_id=du_id)
            bts_conf = bts_conf_http_conn_via_lmp
        self.alarms_watcher[alias].watch_alarms(allowed_alarms=allowed_alarms_list, interval=interval,
                                                bts_config=bts_conf, du_id=du_id,
                                                log_dir=base_alarm_dir, timeout=timeout)
        self.alarms_log_dir = os.path.join(base_alarm_dir, 'ALARMS')
        os.makedirs(self.alarms_log_dir, exist_ok=True)

    def stop_watching_alarms(self, bts_id=0, du_id=0):
        """
        Close watcher thread. Mandatory at the end of test where watcher was started.
        :param bts_id: ID of gNB. Default 0.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]. Default 0.
        :return: None
        """
        alias = self.rest_alias.format(bts_id, du_id)

        if alias not in self.alarms_watcher:
            raise Exception("Watching alarms not started - please call start_watching_alarms")
        try:
            self._create_alarms_log_if_alarms_detected(bts_id=bts_id, du_id=du_id)
            self.alarms_watcher[alias].check_detected_alarms()
        except WatchdogNotStarted:
            logging.warning("Alarms watcher is not initialized! Disallowed alarms are NOT TRACKED! "
                            "Start watching alarms beforehand!")
        finally:
            logging.debug("Stop watching alarms")
            self.alarms_watcher[alias].stop_watching_alarms()

    def allow_alarm(self, alarm, bts_id=0, du_id=0):
        """
        Add alarm to allowed alarms for alarms watcher. Run start_watching_alarms beforehand.
        :param alarm: alarm or list of alarms defined by fault name or dict
        :param bts_id: ID of gNB. Default 0.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]. Default 0.
        :return: None
        """
        alias = self.rest_alias.format(bts_id, du_id)
        if isinstance(alarm, str) or isinstance(alarm, dict):
            alarm = [alarm]
        for instance in alarm:
            alarm_params = self._get_alarm_params(instance)
            self.alarms_watcher[alias].allow_alarm(**alarm_params)

    def disallow_alarm(self, alarm, bts_id=0, du_id=0):
        """
        Remove alarm from allowed alarms for alarms watcher. Run start_watching_alarms beforehand.
        :param alarm: alarm or list of alarms defined by fault name or dict
        :param bts_id: ID of gNB. Default 0.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]. Default 0.
        :return: None
        """
        alias = self.rest_alias.format(bts_id, du_id)
        if isinstance(alarm, str) or isinstance(alarm, dict):
            alarm = [alarm]
        for instance in alarm:
            alarm_params = self._get_alarm_params(instance)
            self.alarms_watcher[alias].disallow_alarm(**alarm_params)

    def watch_active_alarms_and_collect_logs_on_unexpected(self, trigger_alarms=None, bts_id=0, du_id=0):
        """
        Start watcher running in background and collecting logs if trigger alarm alarm was detected.
        :param trigger_alarms: alarm that triggers logs collection.
                               If None then logs are collected on any disallowed alarm. Default None.
        :param bts_id: ID of gNB. Default 0.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]. Default 0.
        :return: None
        """
        logging.debug("Activate alarms watcher...")
        alias = self.rest_alias.format(bts_id, du_id)
        self.alarms_watcher[alias].run_when_alarm_detected(trigger_alarms=trigger_alarms,
                                                           callback=self._callback_for_alarm_watcher, bts_id=bts_id,
                                                           du_id=du_id)

    @login_logout
    def check_if_sw_incompatible_alarm_occurred(self, awaiting_time=600, bts_id=0, du_id=0, timeout=30,
                                                check_on_all_rus=False):
        """
        Check if 'Incompatible SW version detected' alarm occurred.
        :param awaiting_time: Time in seconds to wait for the alarm to occur
        :param bts_id: ID of gNB. Default 0.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]. Default 0.
        :param timeout: timeout for admin API
        :param check_on_all_rus: Flag to check if the alarm is present on all RUs. Default False.
        :return: True if the alarm occurred, False otherwise.
        """
        aw = alarms_watchdog()
        start_time = time.monotonic()
        fault_name = "Incompatible SW version detected"
        general_wanted_alarm = aw.create_alarm(fault_name=fault_name)
        wanted_alarms_for_all_rus = []
        if check_on_all_rus:
            all_ru_dist_names = self.ru._get_all_radio_dist_names(bts_id=bts_id, du_id=du_id)
            for dist_name in all_ru_dist_names:
                wanted_alarm = aw.create_alarm(fault_name=fault_name,
                                               unit_path=re.compile(r'.*?{}'.format(dist_name)))
                wanted_alarms_for_all_rus.append(wanted_alarm)

        while time.monotonic() < start_time + time_to_seconds(time=awaiting_time):
            alarms = self.admin.get_active_alarms(connection=self.rest_alias.format(bts_id, du_id),
                                                  timeout=timeout)
            alarms_obj = [aw.create_alarm(fault_name=alarm.get('faultName'), unit_path=alarm.get('configObjectName'))
                          for alarm in alarms]

            if self._check_if_all_rus_enabled(bts_id, du_id):
                return False

            if check_on_all_rus:
                for wanted_alarm in wanted_alarms_for_all_rus:
                    if wanted_alarm not in alarms_obj:
                        logging.info("Alarm not detected on RU: {}".format(dist_name))
                        break
                else:
                    logging.info("Alarm detected on all RUs")
                    return True
            else:
                if general_wanted_alarm in alarms_obj:
                    logging.info(f"{fault_name} alarm occurred")
                    return True
            time.sleep(10)
        else:
            return False

    @login_logout
    def wait_for_alarm_activation(self, fault_id=None, awaiting_time=60, bts_id=0, du_id=0, alarm=None):
        """
        Wait for the selected alarm to appear
        :param fault_id: Alarm fault ID
        :param awaiting_time: Time in seconds to wait for the alarm activation
        :param bts_id: ID of gNB. Default 0.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]. Default 0.
        :param alarm: Alarm dict
        :return: None
        """

        fault_id = alarm['fault_id'] if fault_id is None else fault_id
        self.admin.assert_alarm_active(faultId=fault_id, timeout=awaiting_time,
                                       connection=self.rest_alias.format(bts_id, du_id))

    @login_logout
    def wait_for_alarm_deactivation(self, fault_id=None, awaiting_time=60, bts_id=0, du_id=0, alarm=None):
        """
        Wait for the selected alarm to disappear
        :param fault_id: Alarm fault ID
        :param awaiting_time: Time in seconds to wait for the alarm deactivation
        :param bts_id: ID of gNB. Default 0.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]. Default 0.
        :param alarm: Alarm dict
        :return: None
        """

        fault_id = alarm['fault_id'] if fault_id is None else fault_id
        self.admin.assert_alarm_inactive(faultId=fault_id, timeout=awaiting_time,
                                         connection=self.rest_alias.format(bts_id, du_id))

    @login_logout
    def verify_severity_of_given_alarm(self, alarm_id, alarm_severity, bts_id=0, du_id=0, timeout=30):
        """
        Checking if specified alarm exists on gNB
        :param alarm_id: ID of the alarm
        :param alarm_severity: severity of alarm
        :param bts_id: id of the BTS
        :param du_id: id of the DU
        :param timeout: timeout for admin API
        :return: None
        """
        alarm_list = self.admin.get_active_alarms(connection=self.rest_alias.format(bts_id, du_id), timeout=timeout)
        alarm = {str(alarm['faultId']): str(alarm_severity) for alarm in alarm_list if
                 alarm['severity'] == str(alarm_severity) and alarm['faultId'] == int(alarm_id)}
        if not alarm:
            raise Exception("Alarm with id {} doesn't exists".format(alarm_id))
        else:
            logging.info("There are existing alarm: {}".format(alarm))

    @login_logout
    def check_if_critical_alarm_exist(self, bts_id=0, du_id=0, timeout=30):
        """
        Checking if any critical alarm exists on gNB
        :param bts_id: id of the BTS
        :param du_id: id of the DU
        :param timeout: timeout for admin API
        :return: None
        """
        alarm_list = self.admin.get_active_alarms(connection=self.rest_alias.format(bts_id, du_id), timeout=timeout)
        critical_alarm_list = [alarm['faultId'] for alarm in alarm_list if alarm['severity'] == 'Critical']
        if critical_alarm_list:
            raise Exception("Critical alarms: {}".format(critical_alarm_list))

    @login_logout
    def get_all_active_alarms(self, bts_id=0, du_id=0, timeout=30):
        """
        Get a list of active alarms
        :param bts_id: ID of BTS
        :param du_id: id of the DU
        :param timeout: timeout for admin API
        :return: List of active alarms
        """
