    @login_to_nom_if_needed
    def get_all_active_alarms_via_nom(self, filters=None, bts_id=0, du_id=0):
        filters = [
            {
                "attribute_name": "integratedId",
                "operator": "EQ",
                "attribute_value": "MRBTS-{}".format(self.get_bts_instance_id(bts_id, du_id))
            }
        ]
        alarms = NomWrapper().nom.get_active_alarms(filters=filters)
        logging.debug(alarms)
        return alarms

    def wait_until_callback_logs_collection_finished(self, timeout=1200, interval=30):
        """
        Wait in case _callback_for_alarm_watcher is running
        :param timeout: max time for wait
        :param interval: checking interval
        :return: None
        """
        if not self.logs_collection_in_progress:
            logging.debug("Callback not triggered - skip waiting")
            return
        start_time = time.time()
        while self.logs_collection_in_progress and (time.time() < start_time + time_to_seconds(time=timeout)):
            logging.debug("Callback logs collection IN PROGRESS - wait {} seconds".format(interval))
            time.sleep(time_to_seconds(time=interval))
        logging.debug("Callback is finished")

    def _callback_for_alarm_watcher(self, bts_id=0, du_id=0, timeout=1200.0, rerun_step=20.0):
        """
        Collect logs when disallowed alarm detected.
        :param timeout: time in seconds callback tries to collect logs
        :param rerun_step: time in seconds between tries
        :param bts_id: ID of gNB. Default 0.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]. Default 0.
        :return: None
        """
        if self.logs_collection_in_progress:
            self._write_to_debug_log("Collecting logs already started. Return...")
            return
        else:
            if self._logs_collection_end_timestamp:
                last_logs_collection_time = round(time.time(), 1) - self._logs_collection_end_timestamp
                if last_logs_collection_time < 600.0:
                    self._write_to_debug_log("Last logs collections ended {} seconds ago -"
                                             " skip trigger next collection".format(last_logs_collection_time))
                    return
            self.logs_collection_in_progress = True

        msg = "Disallowed alarm detected. Starting callback..."
        self._write_to_debug_log(msg)
        logging.warning(msg)

        start_time = round(time.time(), 1)
        callback_log_dir = "{}/unexpected_alarm{}".format(self.alarms_log_dir, start_time)
        logs_collectors = [self.log.collect_snapshot]
        while logs_collectors:
            try:
                current_time = round(time.time(), 1)
                if current_time - start_time > timeout:
                    self._write_to_debug_log(
                        "Timeout for logs collection exceeded {}s > {}s".format(current_time - start_time, timeout))
                    break
                self._collect_logs(logs_collectors=logs_collectors, log_dir=callback_log_dir,
                                   bts_id=bts_id, du_id=du_id)
                if logs_collectors:
                    continue
                self.logs_collection_in_progress = False
                self._write_to_debug_log("Callback was executed successfully")
                break
            except (AdminApiConnectionClosedException, AdminApiProcedureTimeoutException,
                    AdminApiProcedureFailureException) as e:
                self._write_to_debug_log("Caught exception in callback: {}".format(e))
                if 'rat reset is ongoing' in "{}".format(e):
                    time.sleep(60)
                time.sleep(rerun_step)
        self.logs_collection_in_progress = False

    def _collect_logs(self, logs_collectors, log_dir, bts_id=0, du_id=0):
        """
        Collect set of default logs
        :param log_dir: directory where logs are stored
        :param bts_id: ID of gNB. Default 0.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]. Default 0.
        :return: None
        """
        self._write_to_debug_log("Collecting logs using {}".format(logs_collectors))
        for logs_collector in logs_collectors:
            self._write_to_debug_log("start collector {}".format(logs_collector))
            logs_collector(log_dir=log_dir, bts_id=bts_id, du_id=du_id)
            self._write_to_debug_log("collector finished {}, removing...".format(logs_collector))
            logs_collectors.remove(logs_collector)
        self._write_to_debug_log("Logs collected to: {}".format(log_dir))
        self._logs_collection_end_timestamp = round(time.time(), 1)

    def _create_alarms_log_if_alarms_detected(self, bts_id=0, du_id=0):
        """
        Create log file where detected alarms are stored
        :return: None
        """
        alias = self.rest_alias.format(bts_id, du_id)
        detected_alarms = self.alarms_watcher[alias].get_detected_alarms()
        if detected_alarms:
            self.alarm_log_path = "{}/alarm.log".format(self.alarms_log_dir)
            with open(self.alarm_log_path, "a+") as f:
                f.writelines(["{}\n".format(repr(alarm)) for alarm in detected_alarms])
            logging.debug("Alarms log file: [{}]".format(self.alarm_log_path))

    def _write_to_debug_log(self, msg):
        """
        Write message to alarms debug log.
        :param msg: string to write into log
        :return: None
        """
        with open(self.alarms_log_dir + "/debug.log", "a+") as dbg:
            dbg.write("{}  |  {}\n".format(time.ctime(), msg))

    def _convert_to_alarms_objects(self, alarms_list):
        """
        Create list of alarm objects from list of fault names
        :param alarms_list: list of  faults' names or fault id or dict of params.
                            dict could contain keys from admin response or keys aligned to create_alarm
                            method params from taf.ul.watchdog_alarms
        Available formats:
            alarm1 = [
                'LMP connectivity detected',
            ]

            alarm2 = [
                61648
            ]

            alarm3 = [
                {
                    'alarm_id': '7220',
                    'fault_id': '61648',
                    'fault_name': 'LMP connectivity detected',
                    'severity': 'Minor'
                },
            ]

            alarm4 = [
                {
                    'number': '7220',
                    'faultId': '61648',
                    'faultName': 'LMP connectivity detected',
                    'severity': 'Minor'
                },
            ]
        :return: None
        """
        aw = alarms_watchdog()
        alarm_instances = []
        for alarm in alarms_list:
            alarm_params = self._get_alarm_params(alarm)
            alarm_instances.append(aw.create_alarm(**alarm_params))

        return alarm_instances

    @staticmethod
    def _get_alarm_params(alarm):
        if not isinstance(alarm, dict):
            try:
                fault_id = int(alarm)
                alarm = {'fault_id': fault_id}
            except ValueError:
                alarm = {'fault_name': alarm}
        else:
            if 'faultName' in alarm or 'faultId' in alarm:
                alarm = {
                    'fault_id': alarm.get('faultId'),
                    'fault_name': alarm.get('faultName'),
                    'alarm_id': alarm.get('number'),
                    'hw_path': alarm.get('hwPath'),
                    'severity': alarm.get('severity'),
                    'reason': alarm.get('supplAlarmInfo'),
                    'unit_path': alarm.get('configObjectName'),
                    'impacted_cells_count': alarm.get('impactedCell'),
                }
        return alarm

    @login_logout
    def verify_alarm_occurrences(self, fault_name, occurrences, bts_id=0, du_id=0, timeout=30):
        """
        Verify number of occurrences of active alarm
        :param fault_name:      name of fault
        :param occurrences:     expected number of occurrences
        :param bts_id:          ID of BTS
        :param du_id:           DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param timeout:         timeout for admin API
        :return: None
        """
        alarms = self.admin.get_active_alarms(connection=self.rest_alias.format(bts_id, du_id), timeout=timeout)
        counter = self._count_alarm_occurrences(alarms=alarms, fault_name=fault_name)
        if int(counter) != int(occurrences):
            raise AlarmIsNotActive(
                "Alarm {} is active {} times, but should be active {} times".format(fault_name, counter, occurrences))
        logging.info("Alarm {} is active {} times".format(fault_name, counter))

    def _count_alarm_occurrences(self, alarms, fault_name):
        """
        Count occurrences of active alarm
        :param alarms:          list active alarms on gnb
        :param fault_name:      name of fault
        :return:                number of alarm occurrences
        """
        alarm_parameters = {
            "faultName": fault_name
        }
        counter = 0
        for alarm in alarms:
            for key in alarm_parameters:
                if alarm_parameters[key] == alarm[key]:
                    counter += 1
        return counter

    def _check_if_all_rus_enabled(self, bts_id=0, du_id=0):
        """
        Check if all available radio modules are in 'enabled' operationalState.

        :param bts_id:          ID of BTS
        :param du_id:           DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:                True/False according to operationalState of all radio modules
        """
        rus_states = []
        rus_info = self.admin.get_bts_info(connection=self.rest_alias.format(bts_id, du_id))["radioModules"]
        [rus_states.append(rmod["status"]["operationalState"]) for rmod in rus_info["rmod"]]
        [rus_states.append(asirmod["status"]["operationalState"]) for asirmod in rus_info["asirmod"]]
        if rus_states.count("enabled") == len(rus_states) and len(rus_states) != 0:
            return True
        else:
            return False

    @login_logout
    def wait_for_alarm_and_verify_fault_signature_not_empty(self, fault_id, signature_params_patterns=None,
                                                            timeout=60, bts_id=0, du_id=0, operation_timeout=30):
        """
        Wait for expected alarm and verify that its fault signature mandatory parameters are not empty.

        :param fault_id:                   fault ID of expected alarm
        :param signature_params_patterns:  dict with signature mandatory parameters names and regex patterns to verify
                                           if empty default_signature_params_patterns will be used
        :param timeout:                    timeout for waiting for alarm
        :param bts_id:                     ID of BTS
        :param du_id:                      DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param operation_timeout:          timeout for admin API
        """

        default_signature_params_patterns = {'date': '^\\d',
                                             'resetCounter': '^\\d',
                                             'category': '^[a-zA-Z]',
                                             'loadName': '^S',
                                             'scope': '^[a-zA-Z]',
                                             'component': '^[a-zA-Z]'}
        fault_signature = None
        fault_signature_parameters_check = []
        if signature_params_patterns is None:
            signature_params_patterns = default_signature_params_patterns

        self.wait_for_alarm_activation(fault_id=fault_id, awaiting_time=timeout, bts_id=bts_id, du_id=du_id)
        alarms = self.admin.get_active_alarms(connection=self.rest_alias.format(bts_id, du_id),
                                              timeout=operation_timeout)
        for alarm in alarms:
            if alarm['faultId'] == int(fault_id):
                fault_signature = alarm['faultSignature']

        if fault_signature is None:
            raise AlarmIsNotActive("Alarm with fault ID: {} did not appear for {} seconds".format(fault_id, timeout))
        for param in signature_params_patterns.keys():
            pattern = signature_params_patterns[param]
            if not re.search(pattern, str(fault_signature[param])):
                fault_signature_parameters_check.append([param, fault_signature[param], pattern])

        if fault_signature_parameters_check:
            raise FaultSignatureEmpty("These parameters are empty: {}".format(fault_signature_parameters_check))


